# Initialize the to-do list
to_do_list = []

def add_item():
    """Add an item to the to-do list."""
    item = input("Enter an item to add to the to-do list: ")
    to_do_list.append(item)
    print(f"To-Do List: {to_do_list}")

def remove_item():
    """Remove an item from the to-do list."""
    if to_do_list:
        item_index = int(input("Enter the index of the item to remove (0-based): "))
        if item_index < len(to_do_list):
            del to_do_list[item_index]
            print(f"To-Do List: {to_do_list}")
        else:
            print("Invalid index. Please try again.")
    else:
        print("To-Do list is empty. Add some items first.")

def main():
    while True:
        print("1. Add an item")
        print("2. Remove an item")
        print("3. Display the to-do list")
        print("4. Exit")

        choice = int(input("Enter your choice: "))

        if choice == 1:
            add_item()
        elif choice == 2:
            remove_item()
        elif choice == 3:
            print(f"To-Do List: {to_do_list}")
        elif choice == 4:
            print("Goodbye!")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This program defines three functions: `add_item()`, `remove_item()`, and `main()`. The `main()` function handles user input and calls the appropriate function based on the user's choice. The `add_item()` function adds an item to the to-do list, and the `remove_item()` function removes an item from the to-do list. The `main()` function also displays the to-do list and allows the user to exit the program.
